#include <stdio.h>

int apply(int a, int b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return a / b;
    }
    return 0;
}

int main() {
    int a = 20, b = 4;
    char op = '/';
    printf("%d %c %d = %d\n", a, op, b, apply(a, b, op));
    return 0;
}
